import{_ as a,o as e,c as d,a2 as o}from"./chunks/framework.DGvnA5EY.js";const s="/workbuddy-guide/assets/01-file-tidy.BYdaKh24.png",b=JSON.parse('{"title":"第 12 章 从整理桌面文件这些小事做起","description":"> 内容来源：WorkBuddy 官方指南与社区实战案例整理（非官方，© 本指南作者，保留所有权利） 桌面乱成垃圾场、下载文件夹塞了几百个无名文件——这种\\"小事\\"最消耗心力， 却最容易被一直拖着。WorkBuddy 能直接操作你电脑上的文件，把它当成保洁： 批量重命名、按类型归档、找重复、挑大文件…","frontmatter":{"title":"第 12 章 从整理桌面文件这些小事做起"},"headers":[],"relativePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 12 章 从整理桌面文件这些小事做起/index.md","filePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 12 章 从整理桌面文件这些小事做起/index.md","lastUpdated":1791615980000}'),n={name:"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 12 章 从整理桌面文件这些小事做起/index.md"};function l(r,t,i,p,h,u){return e(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="第-12-章-从整理桌面文件这些小事做起" tabindex="-1">第 12 章 从整理桌面文件这些小事做起 <a class="header-anchor" href="#第-12-章-从整理桌面文件这些小事做起" aria-label="Permalink to &quot;第 12 章 从整理桌面文件这些小事做起&quot;">​</a></h1><blockquote><p>内容来源：WorkBuddy 官方指南与社区实战案例整理（非官方，© 本指南作者，保留所有权利）</p></blockquote><p>桌面乱成垃圾场、下载文件夹塞了几百个无名文件——这种&quot;小事&quot;最消耗心力， 却最容易被一直拖着。WorkBuddy 能直接操作你电脑上的文件，把它当成保洁： 批量重命名、按类型归档、找重复、挑大文件。<strong>但动文件有风险</strong>，这一章重点教 你安全地让它干，并把整理规则固化成零成本技能。</p><p><img src="'+s+`" alt="一只小黑蹲在一堆散落的文件前，用双手把文件摞整齐" loading="lazy"></p><p><em>配图为示意插画，用于帮助理解&quot;整理文件&quot;，与实际软件界面无关。</em></p><h2 id="一、先想清楚-这次整理要交付什么" tabindex="-1">一、先想清楚：这次整理要交付什么 <a class="header-anchor" href="#一、先想清楚-这次整理要交付什么" aria-label="Permalink to &quot;一、先想清楚：这次整理要交付什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>要说清什么</th><th>示例</th></tr></thead><tbody><tr><td>目标</td><td>整理完要什么状态</td><td>桌面只留常用，其余按类型归档、能按名找到</td></tr><tr><td>受众</td><td>谁会用这些文件</td><td>主要是你自己，可能涉及家人/同事共享目录</td></tr><tr><td>材料</td><td>哪些文件参与整理</td><td>仅&quot;下载&quot;&quot;桌面&quot;两个文件夹，不碰工作盘</td></tr><tr><td>格式</td><td>整理后的目录结构</td><td>按&quot;类型 / 年月&quot;两级目录</td></tr><tr><td>验收</td><td>怎么判断整理成功</td><td>原文件无丢失、备份存在、命名规则一致</td></tr></tbody></table><h2 id="二、先选对-skill-文件整理的组合" tabindex="-1">二、先选对 Skill：文件整理的组合 <a class="header-anchor" href="#二、先选对-skill-文件整理的组合" aria-label="Permalink to &quot;二、先选对 Skill：文件整理的组合&quot;">​</a></h2><p>WorkBuddy 整理本地文件，本质是 <strong>Agent 模式下的本地文件操作能力</strong>，不一定需要 单独技能；但配合下面这些更稳：</p><table tabindex="0"><thead><tr><th>方式 / Skill</th><th>适合处理</th><th>本章怎么用</th><th>注意点</th></tr></thead><tbody><tr><td><strong>通用 Agent（本地文件操作）</strong></td><td>重命名、移动、归档、查找</td><td>直接下指令让它操作指定目录</td><td>必须开启权限确认，永远先预览后执行</td></tr><tr><td><strong>手动复制 / 备份</strong></td><td>整理前的安全网</td><td>先把待整理目录复制一份到备份</td><td>不可逆操作前必做</td></tr><tr><td><strong>Browser Automation</strong></td><td>网盘 / 网页端文件整理</td><td>整理云盘里的散文件</td><td>需要账号授权，注意隐私</td></tr><tr><td><strong>skill-creator（零成本）</strong></td><td>把整理规则固化</td><td>&quot;每周整理下载文件夹&quot;做成技能</td><td>跑顺后固化，下次一句话触发</td></tr></tbody></table><blockquote><p>铁律：动文件的指令，<strong>认准官方源、不开全自动批准</strong>。AI 很听指令，但&quot;删/移&quot; 是不可逆的，这道闸得你守。</p></blockquote><h2 id="三、真实可复制提示词" tabindex="-1">三、真实可复制提示词 <a class="header-anchor" href="#三、真实可复制提示词" aria-label="Permalink to &quot;三、真实可复制提示词&quot;">​</a></h2><h3 id="提示词-1-整理下载文件夹-先列方案-不真动" tabindex="-1">提示词 1｜整理下载文件夹（先列方案，不真动） <a class="header-anchor" href="#提示词-1-整理下载文件夹-先列方案-不真动" aria-label="Permalink to &quot;提示词 1｜整理下载文件夹（先列方案，不真动）&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>整理我的【下载】文件夹，按类型归档到 文档/PDF、图片、安装包、压缩包、其他 五个子目录，</span></span>
<span class="line"><span>文件名保持原样，不要删除任何东西。</span></span>
<span class="line"><span>先只输出你打算怎么整理的方案（哪些移到哪、新建哪些目录），先别真的移动，等我确认。</span></span></code></pre></div><h3 id="提示词-2-批量重命名-统一规则" tabindex="-1">提示词 2｜批量重命名（统一规则） <a class="header-anchor" href="#提示词-2-批量重命名-统一规则" aria-label="Permalink to &quot;提示词 2｜批量重命名（统一规则）&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>把【旅行照片】文件夹里的 IMG_001、IMG_002…… 批量重命名为 旅行-001、旅行-002……</span></span>
<span class="line"><span>按修改时间排序。先列出重命名对照表给我看，确认后再执行。</span></span></code></pre></div><h3 id="提示词-3-找重复-大文件报告-不动手" tabindex="-1">提示词 3｜找重复 + 大文件报告（不动手） <a class="header-anchor" href="#提示词-3-找重复-大文件报告-不动手" aria-label="Permalink to &quot;提示词 3｜找重复 + 大文件报告（不动手）&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>扫描【下载】文件夹，找出内容重复的图片和大于 1GB 的文件，</span></span>
<span class="line"><span>输出一份清单：文件名、大小、重复/大文件标记、建议处理方式。不要删除，只报告。</span></span></code></pre></div><h2 id="四、执行步骤表" tabindex="-1">四、执行步骤表 <a class="header-anchor" href="#四、执行步骤表" aria-label="Permalink to &quot;四、执行步骤表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>步骤</th><th>WorkBuddy 做什么</th><th>你要确认什么</th></tr></thead><tbody><tr><td>1</td><td>扫描目录，列出整理方案/对照表</td><td>目标目录对不对、规则你认不认可</td></tr><tr><td>2</td><td>（你确认后）执行移动/重命名</td><td>是否先做了备份</td></tr><tr><td>3</td><td>输出结果报告</td><td>原文件是否都在、有无误移</td></tr><tr><td>4</td><td>（可选）生成&quot;整理记录&quot;</td><td>方便回退</td></tr></tbody></table><h2 id="五、一条不能破的安全底线" tabindex="-1">五、一条不能破的安全底线 <a class="header-anchor" href="#五、一条不能破的安全底线" aria-label="Permalink to &quot;五、一条不能破的安全底线&quot;">​</a></h2><p><strong>删文件之前，必须你确认；且先备份，再整理。</strong> 正确姿势是：先把要归档/清理的 文件夹复制一份到 <code>备份/桌面整理-日期</code>，确认无误后再处理原件。任何&quot;清理&quot;&quot;删除&quot; &quot;清空&quot;的请求，都让它先列清单，你逐个核对，再批准。宁可多一步，也别丢东西。</p><h2 id="六、零成本-skill-把整理固化成周常" tabindex="-1">六、零成本 Skill：把整理固化成周常 <a class="header-anchor" href="#六、零成本-skill-把整理固化成周常" aria-label="Permalink to &quot;六、零成本 Skill：把整理固化成周常&quot;">​</a></h2><p>跑顺提示词 1 之后，用 <code>skill-creator</code> 固化：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我做一个&quot;每周整理下载文件夹&quot;的技能：</span></span>
<span class="line"><span>每周日自动把下载文件夹按类型归档（文档/图片/安装包/压缩包/其他），</span></span>
<span class="line"><span>先列方案等我确认再执行，从不删除，只移动；并先复制一份到备份目录。</span></span>
<span class="line"><span>触发词：整理下载、周常整理。</span></span></code></pre></div><p>固化后，你只要在自动化里设个每周日的任务（见第一篇第 10 章），整理就自动化了。</p><h2 id="七、实际效果与验收标准" tabindex="-1">七、实际效果与验收标准 <a class="header-anchor" href="#七、实际效果与验收标准" aria-label="Permalink to &quot;七、实际效果与验收标准&quot;">​</a></h2><p><strong>实际效果</strong>：一个整齐、能按名找到的目录，外加一份&quot;备份/整理记录&quot;，心里不慌。</p><p><strong>验收标准</strong>：</p><ul><li>[ ] 原文件无任何丢失（抽样核对）</li><li>[ ] 备份目录存在且完整</li><li>[ ] 命名/归档规则与你确认的方案一致</li><li>[ ] 没有任何文件被删除（除非你明确批准且已备份）</li></ul><h2 id="小白说明书" tabindex="-1">小白说明书 <a class="header-anchor" href="#小白说明书" aria-label="Permalink to &quot;小白说明书&quot;">​</a></h2><blockquote><p><strong>批量重命名</strong>：一次按统一规则给很多文件改名字，不用一个个点。</p><p><strong>去重（Deduplication）</strong>：找出内容相同的重复文件，避免占空间、搞混版本。</p><p><strong>工作区隔离</strong>：把 AI 的操作限制在指定文件夹里，像给它划一块&quot;安全施工区&quot;。</p><p><strong>零成本 Skill</strong>：用 skill-creator 把周常整理固化成专属技能，不写代码。</p></blockquote><h2 id="本章任务清单" tabindex="-1">本章任务清单 <a class="header-anchor" href="#本章任务清单" aria-label="Permalink to &quot;本章任务清单&quot;">​</a></h2><ul><li>[ ] 新建一个整理工作区文件夹，让 AI 先列方案、不真动</li><li>[ ] 用它的方案，安全地把某一类文件归类，并先做备份</li><li>[ ] （进阶）用 skill-creator 把&quot;每周整理下载文件夹&quot;固化成技能</li></ul><hr><p><em>下一篇：第 13 章——远程控制你的电脑，不用发愁不在电脑前。</em></p><hr><p><em>本指南为第三方非官方整理，版权归作者所有，转载请注明出处。</em></p>`,38)])])}const q=a(n,[["render",l]]);export{b as __pageData,q as default};
